INSERT INTO ingredient (id, name, category_id, primary_unit_type_id, default_unit_id, energy_kcal, energy_kj,
                        edible_part_percent, source_id, source_url, variant_of_ingredient_id, is_verified, is_official)
SELECT pg_temp.seed_uuid_v7(), f.name, '01a088b5-a209-7334-a2d2-55cd29be763e', f.primary_unit_type_id, f.default_unit_id,
       f.energy_kcal, f.energy_kj, f.edible_part_percent, f.source_id, f.source_url, NULL, true, true
FROM (SELECT * FROM seed_food ORDER BY source_id) f
ON CONFLICT DO NOTHING;

INSERT INTO ingredient_nutrient_value (id, ingredient_id, nutrient_definition_id, quantity, source_id)
SELECT pg_temp.seed_uuid_v7(), i.id, v.nutrient_id, v.quantity, v.value_source_id
FROM seed_value v JOIN ingredient i ON i.source_id = v.source_id
ON CONFLICT DO NOTHING;

INSERT INTO ingredient_portion (id, ingredient_id, unit_id, grams_per_portion)
SELECT pg_temp.seed_uuid_v7(), i.id, p.unit_id, p.grams
FROM seed_portion p JOIN ingredient i ON i.source_id = p.source_id
WHERE NOT EXISTS (SELECT 1 FROM ingredient_portion x
                  WHERE x.ingredient_id = i.id AND x.unit_id = p.unit_id AND x.grams_per_portion = p.grams);

INSERT INTO search_keyword (id, name)
SELECT pg_temp.seed_uuid_v7(), k.name FROM (SELECT DISTINCT name FROM seed_keyword ORDER BY name) k
ON CONFLICT DO NOTHING;

INSERT INTO ingredient_search_keyword (ingredient_id, search_keyword_id)
SELECT i.id, k.id FROM seed_keyword s
JOIN ingredient i ON i.source_id = s.source_id JOIN search_keyword k ON k.name = s.name
ON CONFLICT DO NOTHING;

DROP TABLE seed_keyword;
DROP TABLE seed_portion;
DROP TABLE seed_value;
DROP TABLE seed_food;
